const data = path.join(directory, 'data'), project = path.join(directory, 'project');
const write = (file, value) => { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, typeof value === 'string' ? value : JSON.stringify(value)); };
write(path.join(project, 'package.json'), { name: 'component-editing-test', type: 'module', dependencies: { react: '19.2.8', 'react-dom': '19.2.8' } });
write(path.join(project, 'tsconfig.json'), { compilerOptions: { baseUrl: '.', paths: { '#components/*': ['src/*'] } } });
fs.symlinkSync(path.join(repo, 'node_modules'), path.join(project, 'node_modules'));
write(path.join(project, 'src/Button.tsx'), `import { Children, cloneElement, useLayoutEffect, type CSSProperties, type ReactElement } from 'react';
type Props = { variant?: 'primary' | 'secondary'; size?: 'sm' | 'lg'; label?: string; disabled?: boolean; count?: number; style?: CSSProperties };
function validateCount(count: number, label: string) { if (count < 0 || (count === 13 && label === 'Save')) throw new Error('Unsupported count for this label'); }
export function Button({ variant = 'primary', size = 'sm', label = 'Save', disabled = false, count = 0, style }: Props) {
  validateCount(count, label);
  return <button disabled={disabled} data-size={size} data-count={count} style={{ padding: size === 'lg' ? '18px 28px' : '8px 16px', backgroundColor: variant === 'primary' ? '#2563eb' : '#e2e8f0', color: variant === 'primary' ? 'white' : '#172554', border: 0, borderRadius: size === 'lg' ? 10 : 6, ...style }}>{label}</button>;
}
export function Opaque({label = 'Opaque'}: {label?: string}) { return <span>{label}</span>; }
export function DefaultStyle({style = {borderRadius: 23, padding: 9}}: {style?: CSSProperties}) { return <button style={style}>Default style</button>; }
function validateChildCount(count: number) { if(count < 0) throw new Error('Negative child count'); }
export function ForwardItem({label = 'Item', count = 0, style, ...props}: {label?: string; count?: number; style?: CSSProperties}) { validateChildCount(count); return <button {...props} style={style} data-count={count}>{label}</button>; }
export function SlotHost({asChild = true, tone = 'blue', children}: {asChild?: boolean; tone?: 'blue' | 'red'; children: ReactElement}) {
  const child = asChild ? Children.only(children) : null;
  const count = child?.props.count;
  useLayoutEffect(() => { if(count === 13) throw new Error('Child rejected during parent layout'); }, [count]);
  if (asChild) { if(child.type !== ForwardItem && child.type !== SlotHost) throw new Error('Original child component identity required'); return cloneElement(child, {'data-host-tone': tone}); }
  return <div data-host-tone={tone}>{children}</div>;
}
type ContractFieldsProps = { requiredText: string; flag?: boolean; nullableText?: string | null; amount?: number; mode?: 'ready' | 'done'; config?: { label: string }; onAction?: () => void; style?: CSSProperties };
export function ContractFields({requiredText, flag, nullableText = null, amount = 2, mode = 'ready', style}: ContractFieldsProps) {
  return <div style={style} data-required={String(requiredText)} data-flag={String(flag)} data-nullable={JSON.stringify(nullableText)} data-amount={String(amount)} data-mode={mode}>{String(requiredText)}</div>;
}
`);
write(path.join(data, 'preferences.json'), { schemaVersion: 1, localePreference: 'zh-CN' });
