const supportedScanSource = `export function ScanOnly({label = 'Scan'}: {label?: string}) { return <span>{label}</span>; }`;
write(scanFile, unsupportedScanSource);
write(path.join(data, 'local-projects.json'), [{ id: project, rootPath: project, canonicalRoot: project, name: 'Component editing QA', addedAt: Date.now() }]);
