write(compositionPath, compositionSource);
const sourceHash = crypto.createHash('sha256').update(compositionSource).digest('hex');
const sourceJsx = parseCompositionFile(compositionSource, { filePath: 'src/Button.compositions.tsx', sourceHash }).editableJsxByExport.get('SourceExample');
const sourceRoot = parseCompositionJsxToNestedRoots(sourceJsx, {}, { Button: { path: 'src/Button.tsx', exportName: 'Button' } })[0];
sourceRoot.id = 'source-frame'; sourceRoot.canvasPosition = { x: 0, y: 370 };
sourceRoot.styles['--inherited-radius'] = '17px';
sourceRoot.children.forEach((child, index) => { child.id = index ? 'source-b' : 'source-a'; delete child.componentEditing.sourceBinding.template; });
sourceRoot.children.push({ id: 'sides', type: 'component', componentName: 'Button', props: { label: 'Sides' }, styles: { padding: '8px 12px 16px 20px', paddingLeft: '24px', margin: '1px 2px', marginTop: '3px', borderRadius: '10px 20px / 30px 40px', borderTopLeftRadius: '9px', '--fixture-radius': '13px', outlineOffset: 'var(--missing-offset, 4px)' } });
sourceRoot.children.push({ id: 'legacy-static', type: 'component', componentName: 'Button', props: { label: 'Legacy', style: { borderRadius: '20px', color: '#fde047' } }, styles: { borderRadius: '8px', fontSize: '15px' } });
