    await waitFor(() => evaluate(shell, '!!document.querySelector(".project-titlebar")').catch(() => false), 'shell');
    await invoke(shell, 'project-tabs:open', { projectId: project });
    editor = await waitFor(() => webContents.getAllWebContents().find(wc => { try { return new URL(wc.getURL()).searchParams.get('projectTab') === project; } catch { return false; } }), 'editor');
    await require('./editor-test-foreground.cjs').foregroundEditor(editor);
    await waitFor(() => evaluate(editor, '!!document.querySelector("[data-canvas-content] [data-element-id=button-a] button")').catch(() => false), 'component fixture');
    const key = (keyCode, modifiers = []) => { editor.sendInputEvent({ type: 'keyDown', keyCode, modifiers }); editor.sendInputEvent({ type: 'keyUp', keyCode, modifiers }); };
    if (await evaluate(editor, 'localStorage.getItem("bingo-editor-mode")!=="design"')) key('j', ['meta']);
    await sleep(600);
    const select = async (id, additive = false) => { await evaluate(editor, `document.querySelector('[data-canvas-content] [data-element-id="${id}"]').dispatchEvent(new MouseEvent('click',{bubbles:true,clientX:100,shiftKey:${additive}}))`); await sleep(220); };
    const prop = name => `[data-component-prop="${name}"]`;
    const accessibleField = async name => (await editor.debugger.sendCommand('Accessibility.getFullAXTree')).nodes.find(node => !node.ignored && ['textbox', 'combobox', 'spinbutton', 'checkbox'].includes(node.role?.value) && node.name?.value === name);
    const text = selector => evaluate(editor, `document.querySelector(${JSON.stringify(selector)})?.textContent || ''`);
    const choose = async (name, label) => { await evaluate(editor, `(()=>{const field=document.querySelector(${JSON.stringify(prop(name))});const toggle=field.querySelector('[data-component-boolean]');if(toggle){const desired=${JSON.stringify(label)}==='开启';const current=toggle.getAttribute('aria-checked');if(current===String(desired)){field.querySelector('[data-component-pin]')?.click();}else if(current==='mixed'&&!desired){field.querySelector('[data-component-boolean-off]').click();}else toggle.click();return;}const select=field.querySelector('select');const option=[...select.options].find(item=>item.textContent===${JSON.stringify(label)});if(!option)throw Error('Missing option');select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));})()`); await sleep(150); };
    const click = async selector => { await evaluate(editor, `document.querySelector(${JSON.stringify(selector)}).click()`); await sleep(150); };
    const input = async (selector, value) => {
      await evaluate(editor, `(()=>{const input=document.querySelector(${JSON.stringify(selector)});input.focus();Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,${JSON.stringify(value)});input.dispatchEvent(new Event('input',{bubbles:true}));})()`);
      await sleep(100); await evaluate(editor, `document.querySelector(${JSON.stringify(selector)}).blur()`); await sleep(150);
    };
    const radius = () => evaluate(editor, 'getComputedStyle(document.querySelector("[data-element-id=button-a] button")).borderRadius');
    const flushSaved = async () => {
      await evaluate(editor, `(()=>{window.__componentFlush=null;const pending=[];window.dispatchEvent(new CustomEvent('bingo:prepare-project-close',{detail:{pending}}));Promise.all(pending).then(()=>window.__componentFlush='ok',error=>window.__componentFlush=String(error));})()`);
      await waitFor(() => evaluate(editor, 'window.__componentFlush'), 'save flush');
      return JSON.parse(fs.readFileSync(pageFile, 'utf8')).canvas.elements.byId;
    };
    await select('broken');
    await waitFor(() => evaluate(editor, '!!document.querySelector("[data-component-parameters]")'), 'broken component parameters');
    check('An originally broken instance keeps its parameter editor available', (await text(prop('count'))).includes('已设置'));
    await input(`${prop('count')} input`, '0');
    check('An originally broken instance can be repaired through its parameters', await evaluate(editor, 'document.querySelector("[data-element-id=broken] button")?.dataset.count === "0"'));
    await select('button-a');
    await waitFor(() => evaluate(editor, '!!document.querySelector("[data-component-parameters]")'), 'parameter panel');
    check('Parameters visible directly in the design panel', await text('[data-component-parameters]'));
    check('Known default is displayed', (await text(prop('size'))).includes('默认'));
    check('Existing radius appears in overrides', (await text('[data-component-overrides]')).includes('12px'));
    await evaluate(editor, 'window.__originalButtonNode=document.querySelector("[data-element-id=button-a] button")');
    await choose('size', 'lg');
    check('Size parameter reaches real component', await evaluate(editor, 'document.querySelector("[data-element-id=button-a] button").dataset.size === "lg"'));
    check('Successful preview preserves the mounted component DOM', await evaluate(editor, 'window.__originalButtonNode===document.querySelector("[data-element-id=button-a] button")'));
    check('Variant switch preserves radius override', await radius() === '12px');
    await click('[data-style-override="borderRadius"] button');
    check('Reset follows current large default', await radius() === '10px');
    key('z', ['meta']); await sleep(250);
    check('Undo restores style override', await radius() === '12px');
    await choose('disabled', '关闭');
    check('Explicit false differs from default', (await text(prop('disabled'))).includes('已设置'));
    await evaluate(editor, `(()=>{const input=document.querySelector('${prop('label')} input');input.focus();Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'');input.dispatchEvent(new Event('input',{bubbles:true}));})()`);
    await sleep(120);
    await evaluate(editor, `document.querySelector('${prop('label')} input').blur()`); await sleep(200);
    check('Empty label remains a real empty string', await evaluate(editor, 'document.querySelector("[data-element-id=button-a] button").textContent === ""'));
    const output = path.join(repo, 'output/component-instance-editing'); fs.mkdirSync(output, { recursive: true });
    fs.writeFileSync(path.join(output, 'component-panel.png'), (await editor.capturePage()).toPNG());
    await select('opaque');
    check('Unverified style interface has a visible limitation', await evaluate(editor, 'document.body.textContent.includes("尚未确认此组件的根节点样式接口")'));
    check('Unsupported component design controls are disabled', await evaluate(editor, '!!document.querySelector("fieldset[disabled]")'));
    await select('opaque-positioned');
    check('Unsupported appearance still exposes its existing outer container', await evaluate(editor, '!!document.querySelector("[data-component-outer-layout]") && !document.querySelector("[data-component-outer-layout] input[disabled]")'));
    await input('[data-outer-layout-property="width"]', '180');
    check('Outer width changes the wrapper without inventing component styling', await evaluate(editor, 'document.querySelector("[data-element-id=opaque-positioned]").style.width==="180px" && !document.querySelector("[data-element-id=opaque-positioned] span").hasAttribute("style")'));
    const outerSaved = await flushSaved();
    check('Outer edits persist with the correct scope and stay out of root overrides', outerSaved['opaque-positioned'].styles.width === '180px' && outerSaved['opaque-positioned'].componentEditing.styleRecords.width.target === 'outer' && !(await text('[data-component-overrides]')).includes('width'));
    await evaluate(editor, 'document.activeElement.blur()'); key('z', ['meta']); await sleep(250);
    check('Outer container edits participate in undo', await evaluate(editor, 'document.querySelector("[data-element-id=opaque-positioned]").style.width==="120px"'));
    await select('button-a');
    await evaluate(editor, `(()=>{window.__componentFlush=null;const pending=[];window.dispatchEvent(new CustomEvent('bingo:prepare-project-close',{detail:{pending}}));Promise.all(pending).then(()=>window.__componentFlush='ok',error=>window.__componentFlush=String(error));})()`);
    await waitFor(() => evaluate(editor, 'window.__componentFlush'), 'save flush');
    const saved = JSON.parse(fs.readFileSync(pageFile, 'utf8')).canvas.elements;
    const button = saved.byId?.['button-a'];
    check('Persisted parameters retain explicit false and empty string', button?.props.disabled === false && button?.props.label === '');
    check('Persisted radius survives undo and save', button?.styles.borderRadius === '12px');
    await input('input[aria-label="Border Radius"]', '16');
    check('Manual style edit reaches component root', await radius() === '16px');
    check('Manual style edit is recorded with editor provenance', (await text('[data-style-override="borderRadius"]')).includes('实例修改'));
    await select('button-b', true);
    check('Multi-selection shows source differences', (await text(prop('label'))).includes('多个值'));
    await choose('size', 'sm');
    check('Batch edit changes only selected parameter', await evaluate(editor, `['button-a','button-b'].every(id=>document.querySelector('[data-element-id="'+id+'"] button').dataset.size==='sm') && document.querySelector('[data-element-id="button-a"] button').textContent==='' && document.querySelector('[data-element-id="button-b"] button').textContent==='Save'`));
    await evaluate(editor, 'document.activeElement.blur()'); key('z', ['meta']); await sleep(250);
    check('One undo restores both selected sizes', await evaluate(editor, `['button-a','button-b'].every(id=>document.querySelector('[data-element-id="'+id+'"] button').dataset.size==='lg')`));
    await select('button-a');
    await input(`${prop('count')} input`, '-1');
    check('Render failure keeps the last committed instance visible', await evaluate(editor, 'document.querySelector("[data-element-id=button-a] button")?.dataset.count === "0"'));
    check('Render failure retains an explicitly uncommitted parameter draft', (await text('[data-component-preview-status="failed"]')).includes('预览失败') && (await text(prop('count'))).includes('未提交草稿'));
    fs.writeFileSync(path.join(output, 'failed-preview.png'), (await editor.capturePage()).toPNG());
    const failedSaved = await flushSaved();
    check('Failed preview never reaches persisted parameters', !Object.hasOwn(failedSaved['button-a'].props, 'count'));
    await input(`${prop('count')} input`, '2');
    check('Correcting a failed parameter retries and commits the real component', await evaluate(editor, 'document.querySelector("[data-element-id=button-a] button")?.dataset.count === "2" && !document.querySelector("[data-component-preview-status]")'));
    await evaluate(editor, 'document.activeElement.blur()'); key('z', ['meta']); await sleep(250);
    check('One undo removes the successful edit without replaying failed drafts', await evaluate(editor, 'document.querySelector("[data-element-id=button-a] button")?.dataset.count === "0"'));
    await select('button-b', true);
    await input(`${prop('count')} input`, '13');
