    const batchSaved = await flushSaved();
    check('A rejected batch does not partially persist', ['button-a','button-b'].every(id => !Object.hasOwn(batchSaved[id].props, 'count')));
    key('z', ['meta']); await sleep(250);
    check('Undo discards a failed draft without touching committed history', await evaluate(editor, `!document.querySelector('[data-component-preview-status]') && ['button-a','button-b'].every(id=>document.querySelector('[data-element-id="'+id+'"] button')?.dataset.size==='lg')`));
    await select('button-a');
    await input(`${prop('count')} input`, '-1');
    await select('opaque'); await select('button-a');
