    check('Restoring compatible component reapplies the retained override', await radius() === '16px');
    fs.writeFileSync(sourceFile, originalSource.replace("size === 'lg' ? 10 : 6", "size === 'lg' ? 22 : 14").replace('disabled = false', 'disabled = true'));
